contracts/core/LandRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";

/// @title LandRegistry — Rongai Blockchain Land Registry
/// @notice Main ledger that tracks all parcels and ownership history

contract LandRegistry is Ownable {

    // ── Registry Entry ─────────────────────────────────────
    struct RegistryEntry {
        string  parcelId;           // e.g. "KJD/RNG/0042/2026"
        string  titleDeedNumber;    // e.g. "KAJIADO/RONGAI/0042"
        string  lrNumber;           // Land Reference Number
        address currentOwner;       // Current owner wallet address
        string  ownerDID;           // Decentralized Identity ID
        string  landUse;            // Residential / Agricultural / Commercial
        uint256 areaSquareMeters;   // Area in square metres
        uint256 landValueKES;       // Assessed value in KES
        bool    isActive;           // Active status
        uint256 registeredAt;       // Registration timestamp
        uint256 lastUpdatedAt;      // Last update timestamp
    }

    // ── Ownership History ──────────────────────────────────
    struct OwnershipRecord {
        address owner;
        string  ownerDID;
        uint256 fromTimestamp;
        uint256 toTimestamp;
        string  transferTxId;
    }

    // ── Storage ────────────────────────────────────────────
    mapping(string => RegistryEntry)          private _registry;         // parcelId → entry
    mapping(string => bool)                   private _parcelRegistered; // parcelId → exists
    mapping(string => OwnershipRecord[])      private _ownershipHistory; // parcelId → history
    mapping(address => string[])              private _ownerParcels;     // owner → parcelIds

    string[] private _allParcelIds;

    // ── Events ─────────────────────────────────────────────
    event ParcelAdded(string indexed parcelId, address indexed owner, string titleDeedNumber);
    event OwnershipTransferred(string indexed parcelId, address indexed from, address indexed to, string txId);
    event ParcelValueUpdated(string indexed parcelId, uint256 newValueKES);
    event ParcelDeactivated(string indexed parcelId);

    // ── Constructor ────────────────────────────────────────
    constructor() Ownable(msg.sender) {}

    // ── Register a New Parcel ──────────────────────────────
    /// @notice Adds a new parcel to the land registry ledger
    function addParcel(
        string memory parcelId,
        string memory titleDeedNumber,
        string memory lrNumber,
        address owner,
        string memory ownerDID,
        string memory landUse,
        uint256 areaSquareMeters,
        uint256 landValueKES
    ) external onlyOwner {
        require(!_parcelRegistered[parcelId],  "Parcel already registered");
        require(owner != address(0),           "Invalid owner address");
        require(areaSquareMeters > 0,          "Area must be greater than zero");

        _registry[parcelId] = RegistryEntry({
            parcelId:         parcelId,
            titleDeedNumber:  titleDeedNumber,
            lrNumber:         lrNumber,
            currentOwner:     owner,
            ownerDID:         ownerDID,
            landUse:          landUse,
            areaSquareMeters: areaSquareMeters,
            landValueKES:     landValueKES,
            isActive:         true,
            registeredAt:     block.timestamp,
            lastUpdatedAt:    block.timestamp
        });

        _parcelRegistered[parcelId] = true;
        _allParcelIds.push(parcelId);
        _ownerParcels[owner].push(parcelId);

        // Record initial ownership
        _ownershipHistory[parcelId].push(OwnershipRecord({
            owner:         owner,
            ownerDID:      ownerDID,
            fromTimestamp: block.timestamp,
            toTimestamp:   0,
            transferTxId:  "INITIAL_REGISTRATION"
        }));

        emit ParcelAdded(parcelId, owner, titleDeedNumber);
    }

    // ── Transfer Ownership on Registry ────────────────────
    /// @notice Updates the registry when a land transfer is completed
    function transferOwnership(
        string memory parcelId,
        address newOwner,
        string memory newOwnerDID,
        string memory transferTxId
    ) external onlyOwner {
        require(_parcelRegistered[parcelId], "Parcel not found in registry");
        require(newOwner != address(0),      "Invalid new owner address");

        RegistryEntry storage entry = _registry[parcelId];
        require(entry.isActive, "Parcel is not active");

        // Close previous ownership record
        uint256 historyLen = _ownershipHistory[parcelId].length;
        if (historyLen > 0) {
            _ownershipHistory[parcelId][historyLen - 1].toTimestamp = block.timestamp;
        }

        address previousOwner = entry.currentOwner;

        // Update registry
        entry.currentOwner  = newOwner;
        entry.ownerDID      = newOwnerDID;
        entry.lastUpdatedAt = block.timestamp;

        // Add new ownership record
        _ownershipHistory[parcelId].push(OwnershipRecord({
            owner:         newOwner,
            ownerDID:      newOwnerDID,
            fromTimestamp: block.timestamp,
            toTimestamp:   0,
            transferTxId:  transferTxId
        }));

        _ownerParcels[newOwner].push(parcelId);

        emit OwnershipTransferred(parcelId, previousOwner, newOwner, transferTxId);
    }

    // ── Update Land Value ──────────────────────────────────
    function updateLandValue(string memory parcelId, uint256 newValueKES)
        external onlyOwner
    {
        require(_parcelRegistered[parcelId], "Parcel not found");
        _registry[parcelId].landValueKES  = newValueKES;
        _registry[parcelId].lastUpdatedAt = block.timestamp;
        emit ParcelValueUpdated(parcelId, newValueKES);
    }

    // ── Deactivate Parcel ──────────────────────────────────
    function deactivateParcel(string memory parcelId) external onlyOwner {
        require(_parcelRegistered[parcelId],  "Parcel not found");
        require(_registry[parcelId].isActive, "Parcel already inactive");
        _registry[parcelId].isActive = false;
        emit ParcelDeactivated(parcelId);
    }

    // ── View Functions ─────────────────────────────────────
    function getParcel(string memory parcelId)
        external view returns (RegistryEntry memory)
    {
        require(_parcelRegistered[parcelId], "Parcel not found");
        return _registry[parcelId];
    }

    function getOwnershipHistory(string memory parcelId)
        external view returns (OwnershipRecord[] memory)
    {
        require(_parcelRegistered[parcelId], "Parcel not found");
        return _ownershipHistory[parcelId];
    }

    function getParcelsByOwner(address owner)
        external view returns (string[] memory)
    {
        return _ownerParcels[owner];
    }

    function totalParcels() external view returns (uint256) {
        return _allParcelIds.length;
    }

    function isParcelRegistered(string memory parcelId)
        external view returns (bool)
    {
        return _parcelRegistered[parcelId];
    }
}

contracts/core/LandTransferContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title LandTransferContract — Rongai Blockchain Land Registry
/// @notice Manages automated land ownership transfers for Kajiado County

contract LandTransferContract is Ownable, ReentrancyGuard {

    // ── Transfer Status Enum ───────────────────────────────
    enum TransferStatus {
        Pending,
        UnderReview,
        Approved,
        Rejected,
        Completed
    }

    // ── Transfer Request Structure ─────────────────────────
    struct TransferRequest {
        string         transferId;        // e.g. "TXN-RNG-2026-00089"
        string         parcelId;          // Land parcel identifier
        address        seller;            // Seller wallet address
        address        buyer;             // Buyer wallet address
        string         sellerDID;         // Seller decentralized identity
        string         buyerDID;          // Buyer decentralized identity
        uint256        agreedPriceKES;    // Agreed sale price in KES
        string         transferType;      // Sale / Gift / Inheritance
        TransferStatus status;            // Current status
        uint256        requestTimestamp;  // When transfer was requested
        uint256        completedAt;       // When transfer was completed
        string         rejectionReason;   // Reason if rejected
        string         ipfsDocHash;       // IPFS hash of supporting documents
    }

    // ── Storage ────────────────────────────────────────────
    mapping(string => TransferRequest) private _transfers;      // transferId → request
    mapping(string => bool)            private _transferExists;  // transferId → exists
    mapping(string => string)          private _parcelActiveTransfer; // parcelId → transferId

    string[] private _allTransferIds;

    // ── Events ─────────────────────────────────────────────
    event TransferInitiated(string indexed transferId, string indexed parcelId, address seller, address buyer);
    event TransferApproved(string indexed transferId, string indexed parcelId);
    event TransferCompleted(string indexed transferId, string indexed parcelId, address indexed newOwner);
    event TransferRejected(string indexed transferId, string reason);

    // ── Constructor ────────────────────────────────────────
    constructor() Ownable(msg.sender) {}

    // ── Initiate Transfer ──────────────────────────────────
    /// @notice Creates a new land transfer request
    function initiateTransfer(
        string memory transferId,
        string memory parcelId,
        address seller,
        address buyer,
        string memory sellerDID,
        string memory buyerDID,
        uint256 agreedPriceKES,
        string memory transferType,
        string memory ipfsDocHash
    ) external onlyOwner {
        require(!_transferExists[transferId],              "Transfer ID already exists");
        require(seller != address(0),                      "Invalid seller address");
        require(buyer  != address(0),                      "Invalid buyer address");
        require(seller != buyer,                           "Seller and buyer cannot be same");
        require(agreedPriceKES > 0,                        "Price must be greater than zero");
        require(
            bytes(_parcelActiveTransfer[parcelId]).length == 0,
            "Parcel already has an active transfer"
        );

        _transfers[transferId] = TransferRequest({
            transferId:       transferId,
            parcelId:         parcelId,
            seller:           seller,
            buyer:            buyer,
            sellerDID:        sellerDID,
            buyerDID:         buyerDID,
            agreedPriceKES:   agreedPriceKES,
            transferType:     transferType,
            status:           TransferStatus.Pending,
            requestTimestamp: block.timestamp,
            completedAt:      0,
            rejectionReason:  "",
            ipfsDocHash:      ipfsDocHash
        });

        _transferExists[transferId]         = true;
        _parcelActiveTransfer[parcelId]     = transferId;
        _allTransferIds.push(transferId);

        emit TransferInitiated(transferId, parcelId, seller, buyer);
    }

    // ── Approve Transfer ───────────────────────────────────
    /// @notice Registry officer approves a pending transfer
    function approveTransfer(string memory transferId) external onlyOwner {
        require(_transferExists[transferId], "Transfer not found");
        TransferRequest storage req = _transfers[transferId];
        require(
            req.status == TransferStatus.Pending ||
            req.status == TransferStatus.UnderReview,
            "Transfer cannot be approved in current status"
        );
        req.status = TransferStatus.Approved;
        emit TransferApproved(transferId, req.parcelId);
    }

    // ── Complete Transfer ──────────────────────────────────
    /// @notice Marks transfer as completed after stamp duty confirmed
    function completeTransfer(string memory transferId)
        external onlyOwner nonReentrant
    {
        require(_transferExists[transferId], "Transfer not found");
        TransferRequest storage req = _transfers[transferId];
        require(req.status == TransferStatus.Approved, "Transfer must be approved first");

        req.status      = TransferStatus.Completed;
        req.completedAt = block.timestamp;

        // Clear active transfer lock on parcel
        delete _parcelActiveTransfer[req.parcelId];

        emit TransferCompleted(transferId, req.parcelId, req.buyer);
    }

    // ── Reject Transfer ────────────────────────────────────
    /// @notice Rejects a transfer request with a reason
    function rejectTransfer(string memory transferId, string memory reason)
        external onlyOwner
    {
        require(_transferExists[transferId], "Transfer not found");
        TransferRequest storage req = _transfers[transferId];
        require(
            req.status == TransferStatus.Pending ||
            req.status == TransferStatus.UnderReview,
            "Transfer cannot be rejected in current status"
        );

        req.status          = TransferStatus.Rejected;
        req.rejectionReason = reason;

        // Clear active transfer lock on parcel
        delete _parcelActiveTransfer[req.parcelId];

        emit TransferRejected(transferId, reason);
    }

    // ── Set Under Review ───────────────────────────────────
    function setUnderReview(string memory transferId) external onlyOwner {
        require(_transferExists[transferId], "Transfer not found");
        require(
            _transfers[transferId].status == TransferStatus.Pending,
            "Transfer must be pending"
        );
        _transfers[transferId].status = TransferStatus.UnderReview;
    }

    // ── View Functions ─────────────────────────────────────
    function getTransfer(string memory transferId)
        external view returns (TransferRequest memory)
    {
        require(_transferExists[transferId], "Transfer not found");
        return _transfers[transferId];
    }

    function getTransferStatus(string memory transferId)
        external view returns (TransferStatus)
    {
        require(_transferExists[transferId], "Transfer not found");
        return _transfers[transferId].status;
    }

    function getActiveTransferForParcel(string memory parcelId)
        external view returns (string memory)
    {
        return _parcelActiveTransfer[parcelId];
    }

    function totalTransfers() external view returns (uint256) {
        return _allTransferIds.length;
    }
}

contracts/core/StampDutyPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title StampDutyPayment — Rongai Blockchain Land Registry
/// @notice Handles stamp duty calculation, escrow and KRA remittance
/// @dev Implements Kenya Stamp Duty Act rates: 2% urban / 4% rural

contract StampDutyPayment is Ownable, ReentrancyGuard {

    // ── Payment Status Enum ────────────────────────────────
    enum PaymentStatus {
        Pending,
        Processing,
        Confirmed,
        Failed,
        Refunded
    }

    // ── Payment Record ─────────────────────────────────────
    struct PaymentRecord {
        string        paymentId;             // e.g. "SDP-RNG-2026-00089"
        string        transferId;            // Linked transfer ID
        string        parcelId;              // Land parcel ID
        address       payer;                 // Buyer address
        uint256       transactionValueKES;   // Sale price in KES
        uint256       stampDutyRatePercent;  // 2 or 4
        uint256       stampDutyAmountKES;    // Calculated duty
        uint256       registrationFeeKES;    // Fixed registration fee
        uint256       totalFeesKES;          // Total amount due
        string        paymentMethod;         // M-Pesa / Bank / Escrow
        string        paymentReference;      // M-Pesa ref or bank ref
        string        kraConfirmationCode;   // KRA iTax confirmation
        PaymentStatus status;                // Current status
        uint256       createdAt;             // Record creation time
        uint256       confirmedAt;           // Payment confirmation time
    }

    // ── Constants (Kenya Land Act rates) ──────────────────
    uint256 public constant URBAN_RATE_PERCENT   = 2;   // 2% for urban land
    uint256 public constant RURAL_RATE_PERCENT   = 4;   // 4% for rural land
    uint256 public constant URBAN_THRESHOLD_KES  = 4_000_000; // KES 4M threshold
    uint256 public constant REGISTRATION_FEE_KES = 5_000;     // Fixed KES 5,000

    // ── Storage ────────────────────────────────────────────
    mapping(string => PaymentRecord) private _payments;     // paymentId → record
    mapping(string => bool)          private _paymentExists; // paymentId → exists
    mapping(string => string)        private _transferPayment; // transferId → paymentId

    string[] private _allPaymentIds;

    // ── Events ─────────────────────────────────────────────
    event PaymentCreated(string indexed paymentId, string indexed transferId, uint256 totalFeesKES);
    event PaymentConfirmed(string indexed paymentId, string kraConfirmationCode);
    event PaymentRefunded(string indexed paymentId, address indexed payer);
    event PaymentFailed(string indexed paymentId, string reason);

    // ── Constructor ────────────────────────────────────────
    constructor() Ownable(msg.sender) {}

    // ── Calculate Stamp Duty ───────────────────────────────
    /// @notice Calculates stamp duty based on Kenya land law
    /// @param transactionValueKES  Sale price in Kenya Shillings
    /// @param isUrban              true = urban (2%), false = rural (4%)
    /// @return stampDuty           Stamp duty amount in KES
    /// @return registrationFee     Fixed registration fee in KES
    /// @return totalFees           Total fees payable in KES
    function calculateDuty(uint256 transactionValueKES, bool isUrban)
        public pure
        returns (
            uint256 stampDuty,
            uint256 registrationFee,
            uint256 totalFees
        )
    {
        require(transactionValueKES > 0, "Transaction value must be greater than zero");

        uint256 rate = isUrban ? URBAN_RATE_PERCENT : RURAL_RATE_PERCENT;
        stampDuty       = (transactionValueKES * rate) / 100;
        registrationFee = REGISTRATION_FEE_KES;
        totalFees       = stampDuty + registrationFee;
    }

    // ── Create Payment Record ──────────────────────────────
    /// @notice Creates a new stamp duty payment record
    function createPayment(
        string memory paymentId,
        string memory transferId,
        string memory parcelId,
        address payer,
        uint256 transactionValueKES,
        bool    isUrban,
        string memory paymentMethod
    ) external onlyOwner {
        require(!_paymentExists[paymentId],           "Payment ID already exists");
        require(payer != address(0),                  "Invalid payer address");
        require(transactionValueKES > 0,              "Value must be greater than zero");
        require(
            bytes(_transferPayment[transferId]).length == 0,
            "Payment already exists for this transfer"
        );

        (
            uint256 stampDuty,
            uint256 regFee,
            uint256 totalFees
        ) = calculateDuty(transactionValueKES, isUrban);

        uint256 rate = isUrban ? URBAN_RATE_PERCENT : RURAL_RATE_PERCENT;

        _payments[paymentId] = PaymentRecord({
            paymentId:            paymentId,
            transferId:           transferId,
            parcelId:             parcelId,
            payer:                payer,
            transactionValueKES:  transactionValueKES,
            stampDutyRatePercent: rate,
            stampDutyAmountKES:   stampDuty,
            registrationFeeKES:   regFee,
            totalFeesKES:         totalFees,
            paymentMethod:        paymentMethod,
            paymentReference:     "",
            kraConfirmationCode:  "",
            status:               PaymentStatus.Pending,
            createdAt:            block.timestamp,
            confirmedAt:          0
        });

        _paymentExists[paymentId]      = true;
        _transferPayment[transferId]   = paymentId;
        _allPaymentIds.push(paymentId);

        emit PaymentCreated(paymentId, transferId, totalFees);
    }

    // ── Confirm Payment ────────────────────────────────────
    /// @notice Confirms payment after KRA iTax verification
    function confirmPayment(
        string memory paymentId,
        string memory kraConfirmationCode,
        string memory paymentReference
    ) external onlyOwner {
        require(_paymentExists[paymentId], "Payment not found");
        PaymentRecord storage rec = _payments[paymentId];
        require(
            rec.status == PaymentStatus.Pending ||
            rec.status == PaymentStatus.Processing,
            "Payment cannot be confirmed in current status"
        );

        rec.status              = PaymentStatus.Confirmed;
        rec.kraConfirmationCode = kraConfirmationCode;
        rec.paymentReference    = paymentReference;
        rec.confirmedAt         = block.timestamp;

        emit PaymentConfirmed(paymentId, kraConfirmationCode);
    }

    // ── Mark Payment Failed ────────────────────────────────
    function markPaymentFailed(string memory paymentId, string memory reason)
        external onlyOwner
    {
        require(_paymentExists[paymentId], "Payment not found");
        require(
            _payments[paymentId].status == PaymentStatus.Pending ||
            _payments[paymentId].status == PaymentStatus.Processing,
            "Payment cannot be failed in current status"
        );
        _payments[paymentId].status = PaymentStatus.Failed;
        emit PaymentFailed(paymentId, reason);
    }

    // ── Refund Payment ─────────────────────────────────────
    function refundPayment(string memory paymentId)
        external onlyOwner nonReentrant
    {
        require(_paymentExists[paymentId], "Payment not found");
        PaymentRecord storage rec = _payments[paymentId];
        require(
            rec.status == PaymentStatus.Pending ||
            rec.status == PaymentStatus.Failed,
            "Only pending or failed payments can be refunded"
        );
        rec.status = PaymentStatus.Refunded;
        emit PaymentRefunded(paymentId, rec.payer);
    }

    // ── View Functions ─────────────────────────────────────
    function getPayment(string memory paymentId)
        external view returns (PaymentRecord memory)
    {
        require(_paymentExists[paymentId], "Payment not found");
        return _payments[paymentId];
    }

    function getPaymentByTransfer(string memory transferId)
        external view returns (PaymentRecord memory)
    {
        string memory paymentId = _transferPayment[transferId];
        require(bytes(paymentId).length > 0, "No payment found for this transfer");
        return _payments[paymentId];
    }

    function isPaymentConfirmed(string memory transferId)
        external view returns (bool)
    {
        string memory paymentId = _transferPayment[transferId];
        if (bytes(paymentId).length == 0) return false;
        return _payments[paymentId].status == PaymentStatus.Confirmed;
    }

    function totalPayments() external view returns (uint256) {
        return _allPaymentIds.length;
    }
}

